/**
 * Unit tests for AnnotationIntrospector.refineDeserializationType.
 * Since AnnotationIntrospector is abstract and the method logic relies on 
 * findDeserializationType, findDeserializationKeyType, and findDeserializationContentType,
 * we use a spy or a concrete implementation to control the return values of these methods.
 */
public class AnnotationIntrospector_refineDeserializationType_TriageGen1Test {

    private TestAnnotationIntrospector introspector;
    private MapperConfig<?> config;
    private TypeFactory tf;

    // Concrete implementation for testing purposes to override the protected find methods
    private static class TestAnnotationIntrospector extends AnnotationIntrospector {
        public Class<?> findDeserializationTypeRet;
        public Class<?> findDeserializationKeyTypeRet;
        public Class<?> findDeserializationContentTypeRet;

        @Override
        public Version version() {
            return Version.v27;
        }

        @Override
        public Class<?> findDeserializationType(Annotated a, JavaType baseType) {
            return findDeserializationTypeRet;
        }

        @Override
        public Class<?> findDeserializationKeyType(Annotated a, JavaType keyType) {
            return findDeserializationKeyTypeRet;
        }

        @Override
        public Class<?> findDeserializationContentType(Annotated a, JavaType contentType) {
            return findDeserializationContentTypeRet;
        }
    }

    @Before
    public void setUp() {
        introspector = new TestAnnotationIntrospector();
        config = mock(MapperConfig.class);
        tf = TypeFactory.defaultInstance();
        when(config.getTypeFactory()).thenReturn(tf);
    }

    @Test
    public void testRefineDeserializationType_NoChanges() throws JsonMappingException {
        Annotated a = mock(Annotated.class);
        JavaType baseType = tf.constructType(String.class);

        introspector.findDeserializationTypeRet = null;
        introspector.findDeserializationKeyTypeRet = null;
        introspector.findDeserializationContentTypeRet = null;

        JavaType result = introspector.refineDeserializationType(config, a, baseType);

        assertEquals(baseType, result);
    }

    @Test
    public void testRefineDeserializationType_RefineMainType() throws JsonMappingException {
        Annotated a = mock(Annotated.class);
        // Base type is Object, but annotation says String
        JavaType baseType = tf.constructType(Object.class);
        introspector.findDeserializationTypeRet = String.class;

        JavaType result = introspector.refineDeserializationType(config, a, baseType);

        assertEquals(String.class, result.getRawClass());
        assertNotSame(baseType, result);
    }

    @Test
    public void testRefineDeserializationType_RefineKeyTypeInMap() throws JsonMappingException {
        Annotated a = mock(Annotated.class);
        // Map<Object, Object>
        JavaType baseType = tf.constructMapType(HashMap.class, Object.class, Object.class);

        introspector.findDeserializationTypeRet = null;
        introspector.findDeserializationKeyTypeRet = String.class;
        introspector.findDeserializationContentTypeRet = null;

        JavaType result = introspector.refineDeserializationType(config, a, baseType);

        assertEquals(String.class, result.getKeyType().getRawClass());
        assertEquals(Object.class, result.getContentType().getRawClass());
    }

    @Test
    public void testRefineDeserializationType_RefineContentTypeInCollection() throws JsonMappingException {
        Annotated a = mock(Annotated.class);
        // List<Object>
        JavaType baseType = tf.constructCollectionType(java.util.List.class, Object.class);

        introspector.findDeserializationTypeRet = null;
        introspector.findDeserializationKeyTypeRet = null;
        introspector.findDeserializationContentTypeRet = Integer.class;

        JavaType result = introspector.refineDeserializationType(config, a, baseType);

        assertEquals(java.util.List.class, result.getRawClass());
        assertEquals(Integer.class, result.getContentType().getRawClass());
    }

    @Test
    public void testRefineDeserializationType_RefineBothKeyAndContentInMap() throws JsonMappingException {
        Annotated a = mock(Annotated.class);
        // Map<Object, Object>
        JavaType baseType = tf.constructMapType(HashMap.class, Object.class, Object.class);

        introspector.findDeserializationTypeRet = null;
        introspector.findDeserializationKeyTypeRet = String.class;
        introspector.findDeserializationContentTypeRet = Integer.class;

        JavaType result = introspector.refineDeserializationType(config, a, baseType);

        assertEquals(String.class, result.getKeyType().getRawClass());
        assertEquals(Integer.class, result.getContentType().getRawClass());
    }

    @Test(expected = JsonMappingException.class)
    public void testRefineDeserializationType_ThrowExceptionOnInvalidMainType() throws JsonMappingException {
        Annotated a = mock(Annotated.class);
        when(a.getName()).thenReturn("MockAnnotated");

        // Use a type that cannot be specialized with the provided class to trigger IllegalArgumentException
        // In Jackson, constructSpecializedType often fails if the new class isn't a subtype or incompatible
        // We simulate this by providing a class that is not a subtype of the base type if the logic checks it,
        // but since the method calls tf.constructSpecializedType, we provide a scenario that triggers the catch.

        // A more reliable way to trigger IllegalArgumentException in tf.constructSpecializedType 
        // is to try and specialize a type with an incompatible class.
        JavaType baseType = tf.constructType(Integer.class);
        introspector.findDeserializationTypeRet = String.class; // String is not Integer

        introspector.refineDeserializationType(config, a, baseType);
    }

    @Test(expected = JsonMappingException.class)
    public void testRefineDeserializationType_ThrowExceptionOnInvalidKeyType() throws JsonMappingException {
        Annotated a = mock(Annotated.class);
        when(a.getName()).thenReturn("MockAnnotated");
        JavaType baseType = tf.constructMapType(HashMap.class, Integer.class, Object.class);

        introspector.findDeserializationTypeRet = null;
        introspector.findDeserializationKeyTypeRet = String.class; // String is not Integer

        introspector.refineDeserializationType(config, a, baseType);
    }

    @Test(expected = JsonMappingException.class)
    public void testRefineDeserializationType_ThrowExceptionOnInvalidContentType() throws JsonMappingException {
        Annotated a = mock(Annotated.class);
        when(a.getName()).thenReturn("MockAnnotated");
        JavaType baseType = tf.constructCollectionType(java.util.List.class, Integer.class);

        introspector.findDeserializationTypeRet = null;
        introspector.findDeserializationKeyTypeRet = null;
        introspector.findDeserializationContentTypeRet = String.class; // String is not Integer

        introspector.refineDeserializationType(config, a, baseType);
    }
}
